from pathlib import Path
from html import escape as e
root=Path(__file__).resolve().parent.parent

def img(name,caption,kind=''):
    kind=kind.replace('dark','cutout')
    path=f'assets/{name}' if name.endswith('.svg') else f'assets/{name}.webp'
    return f'<figure class="study-image {kind}"><a href="{path}" data-zoom aria-label="Enlarge: {e(caption)}"><img src="{path}" alt="{e(caption)}" loading="lazy" decoding="async"><span class="zoom-hint" aria-hidden="true">+</span></a><figcaption>{e(caption)}</figcaption></figure>'
def gallery(items):
    return '<div class="study-gallery '+('one' if len(items)==1 else 'three' if len(items)==3 else '')+'">'+''.join(img(*i) for i in items)+'</div>'
def section(id,title,text,images,extra=[],insights=[],body=''):
    return f'<section class="study-section" id="{id}"><div class="section-opening"><h2>{title}</h2><div><p>{text}</p></div></div>'+gallery(images)+('<div class="insight-list">'+''.join(f'<article><h3>{a}</h3><p>{b}</p></article>' for a,b in insights)+'</div>' if insights else '')+body+'</section>'

