# Reserve each image's layout space before lazy loading to keep section anchors stable.
import re
from PIL import Image
for slug in ['projects']+[p['slug'] for p in projects]:
    page=root/f'{slug}.html'
    html=page.read_text(encoding='utf-8')
    def size_image(match):
        tag=match.group(0)
        source=re.search(r'src="([^"]+)"',tag).group(1)
        if source.endswith('.svg'):
            import xml.etree.ElementTree as ET
            attrs=ET.parse(root/source).getroot().attrib
            w,h=int(attrs['width']),int(attrs['height'])
        else:
            with Image.open(root/source) as image:
                w,h=image.size
        return tag[:-1]+f' width="{w}" height="{h}" style="--asset-max:{w}px">'
    html=re.sub(r'<img\b[^>]*>',size_image,html)
    page.write_text(html,encoding='utf-8')
